window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fd2acb211e7b0563"]={"versions": [{"id": "FIG-fd2acb211e7b0563", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Ea_Init</code>) im Kontext der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Initialisierungssequenz des EEPROM-Abstraktionsmoduls (<code>Ea</code>) durch den ECU State Manager (<code>EcuM</code>) während der Startphase des Steuergeräts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind zwei Instanzen bzw. Komponenten:</p>\n<ul class=\"fig-list\">\n<li><code>EcuM::EcuM</code>: ECU State Manager als Aufrufer.</li>\n<li><code>Ea::Ea</code>: EEPROM Abstraction Module als Diensterbringer.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Interaktionen:</p>\n<ul class=\"fig-list\">\n<li>Synchroner Operationsaufruf <code>Ea_Init ()</code> von <code>EcuM</code> an <code>Ea</code>.</li>\n<li>Explizite synchrone Rückkehrnachricht <code>Ea_Init</code> (gestrichelter Pfeil) von <code>Ea</code> zurück an <code>EcuM</code>.</li>\n<li>Beide Lebenslinien weisen am unteren Ende ein Zersetzungssymbol (zwei verbundene Kreise) auf.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>EcuM::EcuM</code> initiiert den synchronen Funktionsaufruf <code>Ea_Init ()</code> an <code>Ea::Ea</code>.</li>\n<li>Auf der Lebenslinie von <code>Ea::Ea</code> wird ein Ausführungsbalken (Execution Specification) aktiviert, während der Ausführungsbalken von <code>EcuM</code> während des Aufrufs aktiv bleibt.</li>\n<li>Nach Abschluss der Initialisierung erfolgt die synchrone Rückkehr mittels der Reply-Nachricht <code>Ea_Init</code> an <code>EcuM::EcuM</code>.</li>\n<li>Die Ausführung auf Seiten von <code>Ea</code> endet mit der Rückkehr, und die Steuerung kehrt zu <code>EcuM</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die synchrone Art des Initialisierungsaufrufs <code>Ea_Init ()</code>. Das EEPROM-Abstraktionsmodul führt im Rahmen von <code>Ea_Init</code> seine grundlegenden internen Initialisierungsschritte durch und kehrt nach Fertigstellung an den aufrufenden ECU State Manager zurück, bevor weitere Betriebsphasen eingeleitet werden.</p>"}, {"id": "FIG-c39057cda24c53bf", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Ea_Init</code>) im Kontext der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Initialisierungssequenz des EEPROM-Abstraktionsmoduls (<code>Ea</code>) durch den ECU State Manager (<code>EcuM</code>) während der Startphase des Steuergeräts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten mit explizitem Stereotyp <code>«module»</code>:</p>\n<ul class=\"fig-list\">\n<li><code>EcuM::EcuM</code> (<code>«module»</code>): ECU State Manager als Aufrufer.</li>\n<li><code>Ea::Ea</code> (<code>«module»</code>): EEPROM Abstraction Module als Diensterbringer.</li>\n</ul>\n<p class=\"fig-p\">In beiden Modul-Köpfen ist das Zersetzungssymbol (zwei verbundene Kreise) platziert. Am unteren linken Rand befindet sich ein Notizblock mit den Metadaten <code>Status: Proposed by TO as per SWS Ea 2.0.6</code>, <code>Description:</code> und <code>Comments:</code>.</p>\n<p class=\"fig-p\">Schnittstellen und Interaktionen:</p>\n<ul class=\"fig-list\">\n<li>Synchroner Operationsaufruf <code>Ea_Init()</code> von <code>EcuM</code> an <code>Ea</code>.</li>\n<li>Explizite synchrone Rückkehrnachricht <code>Ea_Init</code> (gestrichelter Pfeil) von <code>Ea</code> zurück an <code>EcuM</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>EcuM::EcuM</code> initiiert den synchronen Funktionsaufruf <code>Ea_Init ()</code> an <code>Ea::Ea</code>.</li>\n<li>Auf der Lebenslinie von <code>Ea::Ea</code> wird ein Ausführungsbalken (Execution Specification) aktiviert, während der Ausführungsbalken von <code>EcuM</code> während des Aufrufs aktiv bleibt.</li>\n<li>Nach Abschluss der Initialisierung erfolgt die synchrone Rückkehr mittels der Reply-Nachricht <code>Ea_Init</code> an <code>EcuM::EcuM</code>.</li>\n<li>Die Ausführung auf Seiten von <code>Ea</code> endet mit der Rückkehr, und die Steuerung kehrt zu <code>EcuM</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die synchrone Art des Initialisierungsaufrufs <code>Ea_Init ()</code>. Das EEPROM-Abstraktionsmodul führt im Rahmen von <code>Ea_Init</code> seine grundlegenden internen Initialisierungsschritte durch und kehrt nach Fertigstellung an den aufrufenden ECU State Manager zurück, bevor weitere Betriebsphasen eingeleitet werden.</p>"}], "trans": [{"from": "FIG-fd2acb211e7b0563", "to": "FIG-c39057cda24c53bf", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Lebenslinienköpfe (<code>EcuM::EcuM</code>, <code>Ea::Ea</code>): Ergänzung des Stereotyps <code>«module»</code> sowie Platzierung des Zersetzungssymbols (zwei verbundene Kreise) direkt innerhalb der Kopf-Rechtecke statt am unteren Ende der Lebenslinien.</li>\n<li>Aufruf <code>Ea_Init</code>: Entfernung des Leerzeichens vor den Klammern (<code>Ea_Init ()</code> zu <code>Ea_Init()</code>).</li>\n<li>Diagrammhinweis: Ergänzung einer Notizbox unten links mit Statusfeldern (<code>Status: Proposed by TO as per SWS Ea 2.0.6</code>, <code>Description:</code>, <code>Comments:</code>).</li>\n</ul>"}]};
